import { StatefulSmartContract, assert, ByteString, FixedArray } from 'runar-lang';

class RtSlots extends StatefulSmartContract {
  slots: FixedArray<bigint, 2> = [0n, 0n];

  constructor() {
    super();
  }

  public bump() {
    this.slots[0] = this.slots[0] + 1n;
  }
}

import { StatefulSmartContract, assert, ByteString, FixedArray } from 'runar-lang';

class RtSlotsIdx extends StatefulSmartContract {
  slots: FixedArray<bigint, 2> = [0n, 0n];

  constructor() {
    super();
  }

  public bump(i: bigint) {
    assert(i >= 0n && i < 2n);
    this.slots[i]++;
  }
}

from runar import StatefulSmartContract, Bigint, public


class RtPy(StatefulSmartContract):
    count: Bigint

    def __init__(self, count: Bigint):
        super().__init__(count)
        self.count = count

    @public
    def increment(self):
        self.count = self.count + 1

