import { StatefulSmartContract, SmartContract, assert, ByteString, PubKey, Sig, checkSig, cat, toByteString } from 'runar-lang';

class RtSingle extends StatefulSmartContract {
  count: bigint;

  constructor(count: bigint) {
    super(count);
    this.count = count;
  }

  public increment() {
    this.count = this.count + 1n;
  }

  /** @sighash SINGLE|FORKID */
  public step(sats: bigint) {
    this.addOutput(sats, this.count + 1n);
  }
}

import { StatefulSmartContract, SmartContract, assert, ByteString, PubKey, Sig, checkSig, cat, toByteString } from 'runar-lang';

class RtReadonly extends StatefulSmartContract {
  readonly owner: PubKey;

  constructor(owner: PubKey) {
    super(owner);
    this.owner = owner;
  }

  public unlock(sig: Sig) {
    assert(checkSig(sig, this.owner));
  }
}

import { StatefulSmartContract, SmartContract, assert, ByteString, PubKey, Sig, checkSig, cat, toByteString } from 'runar-lang';

class RtEscrow extends StatefulSmartContract {
  readonly owner: PubKey;
  count: bigint;

  constructor(owner: PubKey, count: bigint) {
    super(owner, count);
    this.owner = owner;
    this.count = count;
  }

  public bump() {
    this.count = this.count + 1n;
  }

  public release(sig: Sig) {
    assert(checkSig(sig, this.owner));
  }
}

